docker exec -i postgres-container psql -U postgres -d postgres -c "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = 'four-tails' AND pid <> pg_backend_pid();" && docker exec -i postgres-container psql -U postgres -d postgres -c "DROP DATABASE IF EXISTS \"four-tails\";" && docker exec -i postgres-container psql -U postgres -d postgres -c "CREATE DATABASE \"four-tails\";" && docker exec -it postgres-container psql -U postgres -d four-tails -c "CREATE EXTENSION postgis; CREATE EXTENSION postgis_topology; SELECT PostGIS_Full_Version();"